function setLang(l){
  if(!I18N[l])return;LANG=l;
  document.documentElement.lang=l;
  document.querySelectorAll('[data-i18n]').forEach(el=>{const v=I18N[l][el.dataset.i18n];if(v)el.textContent=v});
  const L=document.querySelector('.lang');
  if(L){const idx=['en','es','fr'].indexOf(l);L.style.setProperty('--i',idx);L.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.l===l))}
  buildBands(current);
  try{localStorage.setItem('rmt-lang',l)}catch(e){}
}
