function show(name,scrollTo){
  const _v=document.querySelector('[data-view]');if(_v&&document.querySelectorAll('[data-view]').length<2){current=_v.dataset.view;buildBands(current);tick();return}
  const names=[...document.querySelectorAll('[data-view]')].map(e=>e.dataset.view);
  let view=names.includes(name)?name:'home';
  const changed=view!==current;
  document.querySelectorAll('[data-view]').forEach(e=>e.hidden=e.dataset.view!==view);
  current=view;
  buildBands(view);
  if(changed||scrollTo)scrollTo===false?0:window.scrollTo(0,0);
  tick();
}
function go(name){location.href=(name==='home'||!name)?'index.html':name+'.html'}
