function flush(){
  document.querySelectorAll('.rv:not(.rv-on),.rvh:not(.rv-on)').forEach(function(el){
    if(!el.offsetParent)return;var r=el.getBoundingClientRect();
    if(r.top<innerHeight&&r.bottom>0)el.classList.add('rv-on');
  });
}
